import { once } from "events";
import net from "net";
import path from "path";
import { Forwarder } from "@ndn/fw";
import { L3Face } from "@ndn/l3face";
import { joinHostPort, splitHostPort, udp_helper, UdpTransport } from "@ndn/node-transport";
import { GraphQLClient } from "graphql-request";
import { CreateFace, Delete } from "./gql_browser.js";
import { MemifTransport } from "./memif-transport_browser.js";
import { NdndpdkPrefixReg } from "./prefix-reg_browser.js";
const DefaultGqlServer = "http://127.0.0.1:3030";
async function detectLocalAddress(gqlServer) {
    const { host, port = 80 } = splitHostPort(new URL(gqlServer).host);
    if (host === "127.0.0.1") {
        return host;
    }
    const tcpConn = net.connect(port, host);
    try {
        await once(tcpConn, "connect");
        const { localAddress } = tcpConn;
        return localAddress;
    }
    finally {
        tcpConn.destroy();
    }
}
async function openFaceImpl({ gqlServer = DefaultGqlServer, fw = Forwarder.getDefault(), addRoutes, attributes = {}, }, locator, prepareTransport) {
    const client = new GraphQLClient(gqlServer);
    const resp = await client.request(CreateFace, {
        locator,
    });
    const { id, locator: loc } = resp.createFace;
    const prefixReg = new NdndpdkPrefixReg(client, id);
    const cleanup = async () => {
        prefixReg.disable();
        await client.request(Delete, { id });
    };
    let transport;
    let mtu;
    try {
        [transport, mtu] = await prepareTransport(loc);
    }
    catch (err) {
        await cleanup();
        throw err;
    }
    prefixReg.enable(fw);
    const face = fw.addFace(new L3Face(transport, {
        advertiseFrom: false,
        describe: `NDN-DPDK(${id})`,
        ...attributes,
    }, {
        mtu,
    }));
    L3Face.processAddRoutes(face, addRoutes);
    face.addEventListener("close", cleanup, { once: true });
    return face;
}
async function openFaceUdp(opts) {
    const { gqlServer = DefaultGqlServer, localHost = await detectLocalAddress(gqlServer), mtu = 1400, udp: udpOptionsInput, } = opts;
    const sockOpts = {
        bind: { address: localHost },
        ...udpOptionsInput,
    };
    const sock = await udp_helper.openSocket(sockOpts);
    try {
        return await openFaceImpl(opts, {
            scheme: "udp",
            remote: joinHostPort(localHost, sock.address().port),
            mtu,
        }, async (loc) => {
            const { host, port } = splitHostPort(loc.local ?? "");
            if (!host || !port) {
                throw new Error(`unexpected locator: ${JSON.stringify(loc)}`);
            }
            await udp_helper.connect(sock, { host, port });
            return [await UdpTransport.connect(sock), mtu];
        });
    }
    catch (err) {
        sock.close();
        throw err;
    }
}
async function openFaceMemif(opts) {
    const { mtu = 2048, memif: { socketPath = "/run/ndn", dataroom = mtu, ringCapacity = 1024, } = {}, } = opts;
    const socketName = path.join(socketPath, `NDNts-memif-${process.pid}-${Date.now()}.sock`);
    const socketOwner = (process.getuid && process.getgid) ? [process.getuid(), process.getgid()] : undefined;
    return openFaceImpl(opts, {
        scheme: "memif",
        role: "server",
        socketName,
        socketOwner,
        id: 0,
        dataroom,
        ringCapacity,
    }, async () => {
        const transport = await MemifTransport.connect({
            role: "client",
            socketName,
            id: 0,
            dataroom,
            ringCapacity,
        });
        return [transport, dataroom];
    });
}
const openFaceScheme = {
    udp: openFaceUdp,
    memif: openFaceMemif,
};
/** Open a face on NDN-DPDK. */
export async function openFace(opts = {}) {
    const { scheme = "udp" } = opts;
    const face = await openFaceScheme[scheme]?.(opts);
    if (face === undefined) {
        throw new Error(`unknown scheme ${scheme}`);
    }
    return face;
}
